previewCss:
.darma-loader-darma-b17-stained-glass { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #f59e0b); width: calc(var(--loader-size, 116px) * .8); height: var(--loader-size, 116px); position: relative; border-radius: 50% 50% 6px 6px / 32% 32% 6px 6px; overflow: hidden; background: color-mix(in srgb, #0f172a 60%, transparent); }
.darma-loader-darma-b17-stained-glass span { position: absolute; border: 2px solid color-mix(in srgb, #0f172a 70%, transparent); animation: darma-loader-darma-b17-stained-glass-glass-lume calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-stained-glass span:nth-of-type(1) { left: 8%; top: 6%; width: 40%; height: 30%; border-radius: 60% 20% 20% 20%; background: var(--accent); }
.darma-loader-darma-b17-stained-glass span:nth-of-type(2) { right: 8%; top: 6%; width: 40%; height: 30%; border-radius: 20% 60% 20% 20%; background: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b17-stained-glass span:nth-of-type(3) { left: 8%; top: 38%; width: 28%; height: 28%; border-radius: 20%; background: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b17-stained-glass span:nth-of-type(4) { left: 38%; top: 38%; width: 34%; height: 34%; border-radius: 50%; background: color-mix(in srgb, #fff 30%, var(--accent)); animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b17-stained-glass span:nth-of-type(5) { right: 4%; top: 40%; width: 26%; height: 26%; border-radius: 20%; background: var(--accent); animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b17-stained-glass span:nth-of-type(6) { left: 10%; bottom: 4%; width: 80%; height: 26%; border-radius: 20% 20% 8% 8%; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation-delay: calc(var(--loader-speed, 1s) * 1.5); }
.darma-loader-darma-b17-stained-glass .darma-loader-darma-b17-stained-glass__lead { position: absolute; inset: 0; background: linear-gradient(90deg, transparent 48%, color-mix(in srgb, #0f172a 65%, transparent) 48% 52%, transparent 52%), linear-gradient(transparent 36%, color-mix(in srgb, #0f172a 65%, transparent) 36% 40%, transparent 40%); }
@keyframes darma-loader-darma-b17-stained-glass-glass-lume { 0%, 100% { filter: brightness(.55) saturate(.8); } 40% { filter: brightness(1.35) saturate(1.3); } }

